import java.io.*;

public class Rock_Paper_Scissors {
    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = in.readLine()) != null) {
            all.append(line).append(' ');
        }
        String[] tokens = all.toString().trim().split("\\s+");
        int idx = 0;
        int n = Integer.parseInt(tokens[idx++]);
        long[] a = new long[3];
        long[] b = new long[3];
        for (int i = 0; i < 3; i++) {
            a[i] = Long.parseLong(tokens[idx++]);
        }
        for (int i = 0; i < 3; i++) {
            b[i] = Long.parseLong(tokens[idx++]);
        }

        long max = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);

        long min = 0;
        if (a[0] > b[0] + b[2]) min += a[0] - (b[0] + b[2]);
        if (a[1] > b[0] + b[1]) min += a[1] - (b[0] + b[1]);
        if (a[2] > b[1] + b[2]) min += a[2] - (b[1] + b[2]);

        System.out.println(min + " " + max);
    }
}
